import { readFile } from "node:fs/promises";
import { createForks } from "@tigrisdata/agent-kit";
import { put } from "@tigrisdata/storage";

async function main() {
  try {
    // 1. Read the current trial id
    const rawTrialId = await readFile("/logs/artifacts/trial_id", "utf-8");
    const trialId = rawTrialId.trim();

    // Normalize bucket name: lowercase and replace invalid characters (like underscores) with hyphens
    const normalizedTrialId = trialId.toLowerCase().replace(/_/g, "-");

    // 2. Compute sourceBucket and forkPrefix
    const sourceBucket = `harbor-source-${normalizedTrialId}`;
    const forkPrefix = `harbor-fork-${normalizedTrialId}`;

    console.log(`Using source bucket: ${sourceBucket}`);
    console.log(`Using fork prefix: ${forkPrefix}`);

    // 3. Call createForks
    const forkResponse = await createForks(sourceBucket, 3, { prefix: forkPrefix });

    // 4. Check for error and exit non-zero on failure
    if (forkResponse.error) {
      console.error("Error creating forks:", forkResponse.error);
      process.exit(1);
    }

    const forkSet = forkResponse.data;
    if (!forkSet || !forkSet.forks || forkSet.forks.length !== 3) {
      console.error("Unexpected fork response structure or count");
      process.exit(1);
    }

    // 5. Fan out IN PARALLEL with Promise.all to write the object worker/output.txt into each fork
    const writePromises = forkSet.forks.map((fork, i) => {
      const bucketName = fork.bucket;
      const body = `worker-${i}`;
      console.log(`Writing to ${bucketName}: ${body}`);
      return put("worker/output.txt", body, { config: { bucket: bucketName } });
    });

    await Promise.all(writePromises);

    // 6. Print the resulting fork bucket names to stdout
    forkSet.forks.forEach((fork) => {
      console.log(fork.bucket);
    });

  } catch (error) {
    console.error("Program failed:", error);
    process.exit(1);
  }
}

main();

